theme_update(panel.grid.minor = element_blank())
library("ggfunction")

ggplot() +
  geom_pdf(
    fun = dnorm, xlim = c(-3.5, 3.5),
    support = c(-Inf, Inf), p_lower = 0.025, p_upper = 0.975
